import pytest
from subject import (
    parse_event_bus,
    ModelEventBusParseResult,
    ModelEventBusSubscription,
    EventBusContractShapeError,
)

def test_missing_event_bus_returns_empty():
    assert parse_event_bus({}) == ModelEventBusParseResult()
    assert parse_event_bus({"other": 1}) == ModelEventBusParseResult()

def test_event_bus_not_dict_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": "not a dict"})
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": ["a"]})
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": 123})

def test_event_bus_unknown_key_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"foo": 1}})
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe_topics": [], "extra": 2}})

def test_classic_shape_valid():
    res = parse_event_bus({"event_bus": {"subscribe_topics": ["a.b", "c.d"]}})
    expected = ModelEventBusParseResult(
        subscriptions=[
            ModelEventBusSubscription(topic="a.b"),
            ModelEventBusSubscription(topic="c.d"),
        ]
    )
    assert res == expected

def test_classic_shape_non_list_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe_topics": "not a list"}})
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe_topics": 42}})

def test_classic_shape_element_not_string_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe_topics": ["ok", 1]}})
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe_topics": [None]}})

def test_nested_shape_valid():
    res = parse_event_bus(
